import inspect
import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing the same algorithm as the CuTe/CUDA kernel,
# now restructured with CTA-level output/spatial tiling + shared-memory
# staging of the reusable input activation tile:
#   - grid = (ceil(Hout/TILE_OH), ceil(Cout/OC_PER_BLOCK), N)
#   - block = (THREADS, 1, 1)
#   - each block caches OC_PER_BLOCK output-channel filters AND a padded
#     input tile (Cin x IH_TILE x IW_TILE) covering exactly the receptive
#     field needed for its TILE_OH output rows into shared memory
#   - all threads in the block then reuse that cached input tile while
#     computing the TILE_OH*Wout output pixels for the 4 output channels,
#     avoiding redundant global-memory re-fetches of overlapping input
#     pixels between neighboring output rows/columns
# ---------------------------------------------------------------------------

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.shared .align 16 .b8 smem_raw[20724];

.visible .entry conv2d_kernel(
    .param .u64 p_X,
    .param .u64 p_W,
    .param .u64 p_B,
    .param .u64 p_Y,
    .param .u32 p_N,
    .param .u32 p_Cin,
    .param .u32 p_H,
    .param .u32 p_Win,
    .param .u32 p_Cout,
    .param .u32 p_K,
    .param .u32 p_stride,
    .param .u32 p_padding,
    .param .u32 p_Hout,
    .param .u32 p_Wout
)
{
    .reg .pred %p<30>;
    .reg .b32 %r<170>;
    .reg .b64 %rd<70>;
    .reg .f32 %f<70>;

    ld.param.u64 %rd1, [p_X];
    ld.param.u64 %rd2, [p_W];
    ld.param.u64 %rd3, [p_B];
    ld.param.u64 %rd4, [p_Y];
    ld.param.u32 %r1, [p_N];
    ld.param.u32 %r2, [p_Cin];
    ld.param.u32 %r3, [p_H];
    ld.param.u32 %r4, [p_Win];
    ld.param.u32 %r5, [p_Cout];
    ld.param.u32 %r6, [p_K];
    ld.param.u32 %r7, [p_stride];
    ld.param.u32 %r8, [p_padding];
    ld.param.u32 %r9, [p_Hout];
    ld.param.u32 %r10, [p_Wout];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r11, %ctaid.z;   // n
    mov.u32 %r12, %ctaid.y;   // oc block index
    mov.u32 %r13, %tid.x;
    mov.u32 %r14, %ntid.x;
    mov.u32 %r15, %ctaid.x;   // combined oh_tile*NUM_OW_TILES + ow_tile index
    mov.u32 %r140, 2;         // NUM_OW_TILES (two column tiles per output row now that TILE_OW=32 shrinks the cached input tile, cutting per-CTA static shared memory so more CTAs can co-reside per SM, raising occupancy)
    div.u32 %r141, %r15, %r140;  // oh_tile_idx
    rem.u32 %r142, %r15, %r140;  // ow_tile_idx
    mov.u32 %r16, 2;              // OC_PER_BLOCK
    mul.lo.s32 %r17, %r12, %r16;  // oc_start
    mov.u32 %r18, 1;              // TILE_OH (reduced from 2 to shrink per-CTA shared-mem footprint and raise achieved occupancy)
    mul.lo.s32 %r19, %r141, %r18; // oh_tile_start
    mov.u32 %r143, 32;            // TILE_OW (narrowed from 64 to 32 to shrink the cached input tile (IW_TILE) and thus the static shared-memory footprint per CTA, letting more CTAs co-reside per SM concurrently; directly targets the profiler's shared-memory-limited theoretical-occupancy signal by roughly doubling co-resident CTAs per SM)
    mul.lo.s32 %r144, %r142, %r143;  // ow_tile_start
    // row_start = oh_tile_start*stride - padding
    mul.lo.s32 %r20, %r19, %r7;
    sub.s32 %r20, %r20, %r8;
    // col_start = ow_tile_start*stride - padding
    mul.lo.s32 %r120, %r144, %r7;
    sub.s32 %r120, %r120, %r8;
    // IH_TILE = (TILE_OH-1)*stride + K
    sub.s32 %r21, %r18, 1;
    mul.lo.s32 %r21, %r21, %r7;
    add.s32 %r21, %r21, %r6;
    // IW_TILE = (TILE_OW-1)*stride + K
    sub.s32 %r22, %r143, 1;
    mul.lo.s32 %r22, %r22, %r7;
    add.s32 %r22, %r22, %r6;

    // WSZ = OC_PER_BLOCK*Cin*K*K
    mul.lo.s32 %r23, %r2, %r6;
    mul.lo.s32 %r23, %r23, %r6;   // Cin*K*K
    mul.lo.s32 %r24, %r23, %r16;  // WSZ
    mul.lo.s32 %r26, %r6, %r6;    // K*K
    mul.lo.s32 %r100, %r23, 4;    // weight group stride in bytes

    mov.u32 %r27, smem_raw;
    mul.lo.s32 %r29, %r24, 4;
    add.s32 %r30, %r27, %r29;     // input tile base (shared)

    // ---- Load weight cache: WSZ elements ----
    mov.u32 %r31, %r13;
LOOP_W:
    setp.ge.s32 %p1, %r31, %r24;
    @%p1 bra LOOP_W_DONE;

    div.s32 %r32, %r31, %r23;     // oc_local
    rem.s32 %r33, %r31, %r23;
    div.s32 %r34, %r33, %r26;     // ic
    rem.s32 %r35, %r33, %r26;
    div.s32 %r36, %r35, %r6;      // kh
    rem.s32 %r37, %r35, %r6;      // kw

    add.s32 %r38, %r17, %r32;     // oc

    mov.f32 %f1, 0f00000000;
    setp.ge.s32 %p2, %r38, %r5;
    @%p2 bra STORE_W;

    mad.lo.s32 %r39, %r38, %r2, %r34;
    mad.lo.s32 %r39, %r39, %r6, %r36;
    mad.lo.s32 %r39, %r39, %r6, %r37;
    mul.wide.s32 %rd10, %r39, 4;
    add.s64 %rd11, %rd2, %rd10;
    ld.global.f32 %f1, [%rd11];

STORE_W:
    mul.lo.s32 %r40, %r31, 4;
    add.s32 %r41, %r27, %r40;
    st.shared.f32 [%r41], %f1;

    add.s32 %r31, %r31, %r14;
    bra LOOP_W;
LOOP_W_DONE:

    // ---- Load input tile cache: Cin*IH_TILE*IW_TILE elements ----
    mul.lo.s32 %r42, %r21, %r22;   // IH_TILE*IW_TILE
    mul.lo.s32 %r43, %r42, %r2;    // ISZ

    mul.lo.s32 %r44, %r2, %r3;
    mul.lo.s32 %r44, %r44, %r4;    // Cin*H*Win
    mul.wide.s32 %rd12, %r44, %r11;
    shl.b64 %rd13, %rd12, 2;
    add.s64 %rd14, %rd1, %rd13;    // X base for image n

    mul.lo.s32 %r45, %r3, %r4;     // H*Win

    mov.u32 %r46, %r13;
LOOP_I:
    setp.ge.s32 %p3, %r46, %r43;
    @%p3 bra LOOP_I_DONE;

    div.s32 %r47, %r46, %r42;      // ic
    rem.s32 %r48, %r46, %r42;
    div.s32 %r49, %r48, %r22;      // pr
    rem.s32 %r50, %r48, %r22;      // pc

    add.s32 %r51, %r20, %r49;      // global_row
    add.s32 %r52, %r50, %r120;      // global_col = col_start + pc

    mov.f32 %f2, 0f00000000;

    setp.lt.s32 %p4, %r51, 0;
    setp.ge.s32 %p5, %r51, %r3;
    or.pred %p6, %p4, %p5;
    setp.lt.s32 %p7, %r52, 0;
    setp.ge.s32 %p8, %r52, %r4;
    or.pred %p9, %p7, %p8;
    or.pred %p10, %p6, %p9;
    @%p10 bra STORE_I;

    mul.lo.s32 %r53, %r47, %r45;
    mad.lo.s32 %r53, %r51, %r4, %r53;
    add.s32 %r53, %r53, %r52;

    mul.wide.s32 %rd15, %r53, 4;
    add.s64 %rd16, %rd14, %rd15;
    ld.global.f32 %f2, [%rd16];

STORE_I:
    mul.lo.s32 %r54, %r46, 4;
    add.s32 %r55, %r30, %r54;
    st.shared.f32 [%r55], %f2;

    add.s32 %r46, %r46, %r14;
    bra LOOP_I;
LOOP_I_DONE:

    bar.sync 0;

    // ---- Compute phase ----
    mul.lo.s32 %r56, %r18, %r143;   // TW = TILE_OH*TILE_OW

    mul.lo.s32 %r57, %r5, %r9;
    mul.lo.s32 %r57, %r57, %r10;
    mul.wide.s32 %rd17, %r57, %r11;
    shl.b64 %rd18, %rd17, 2;
    add.s64 %rd19, %rd4, %rd18;    // Y base for image n

    mov.u32 %r150, 8;               // GROUP_SIZE: cooperative reduction lanes per output pixel
    div.u32 %r151, %r13, %r150;     // group_id (0..31), one group per output pixel in the tile
    rem.u32 %r152, %r13, %r150;     // lane_in_group (0..7)
    div.u32 %r59, %r151, %r143;     // oh_local
    rem.u32 %r60, %r151, %r143;     // ow_local
    add.s32 %r61, %r19, %r59;       // oh_abs
    setp.ge.s32 %p12, %r61, %r9;
    @%p12 bra COMPUTE_DONE;
    add.s32 %r145, %r144, %r60;     // ow_abs = ow_tile_start + ow_local
    setp.ge.s32 %p18, %r145, %r10;
    @%p18 bra COMPUTE_DONE;
    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.u32 %r155, %r152;           // reduction index, starts at lane_in_group
    div.s32 %r156, %r152, %r26;     // ic (initial decomposition, done once)
    rem.s32 %r157, %r152, %r26;     // kk = kh*K+kw (initial)
    div.s32 %r158, %r157, %r6;      // kh (initial)
    rem.s32 %r159, %r157, %r6;      // kw (initial)
LOOP_R:
    setp.ge.s32 %p13, %r155, %r23;  // r23 = Cin*K*K (total reduction length)
    @%p13 bra LOOP_R_DONE;
    mad.lo.s32 %r64, %r59, %r7, %r158;   // pr = oh_local*stride+kh
    mul.lo.s32 %r92, %r64, %r22;
    mul.lo.s32 %r90, %r156, %r42;        // ic*(IH_TILE*IW_TILE)
    add.s32 %r92, %r92, %r90;            // input row base
    mad.lo.s32 %r66, %r60, %r7, %r159;   // pc = ow_local*stride+kw
    add.s32 %r67, %r92, %r66;
    mul.lo.s32 %r68, %r67, 4;
    add.s32 %r69, %r30, %r68;
    ld.shared.f32 %f20, [%r69];
    mul.lo.s32 %r91, %r156, %r26;        // ic*(K*K)
    mul.lo.s32 %r93, %r158, %r6;
    add.s32 %r93, %r93, %r91;
    add.s32 %r70, %r93, %r159;
    mul.lo.s32 %r71, %r70, 4;
    add.s32 %r72, %r27, %r71;
    ld.shared.f32 %f21, [%r72];
    fma.rn.f32 %f10, %f20, %f21, %f10;
    add.s32 %r74, %r72, %r100;
    ld.shared.f32 %f22, [%r74];
    fma.rn.f32 %f11, %f20, %f22, %f11;
    // ---- incremental (division-free) index update: rather than
    // recomputing ic/kh/kw from scratch via div.s32/rem.s32 every
    // iteration (four expensive integer division-class ops), advance
    // kw by GROUP_SIZE with a predicated carry into kh and then into
    // ic. GROUP_SIZE < K so at most a single carry step is ever
    // needed per level, replacing 4 divisions/iteration with a
    // handful of cheap add/setp/sub/selp ops -- directly reduces the
    // redundant integer compute the profiler flagged in this
    // compute-bound reduction loop. ----
    add.s32 %r161, %r159, %r150;         // kw + GROUP_SIZE
    setp.ge.s32 %p20, %r161, %r6;
    sub.s32 %r162, %r161, %r6;
    selp.b32 %r159, %r162, %r161, %p20;  // new kw
    selp.b32 %r163, 1, 0, %p20;          // carry into kh
    add.s32 %r164, %r158, %r163;
    setp.ge.s32 %p21, %r164, %r6;
    sub.s32 %r165, %r164, %r6;
    selp.b32 %r158, %r165, %r164, %p21;  // new kh
    selp.b32 %r166, 1, 0, %p21;          // carry into ic
    add.s32 %r156, %r156, %r166;         // new ic
    add.s32 %r155, %r155, %r150;
    bra LOOP_R;
LOOP_R_DONE:
    // ---- 8-lane segmented butterfly reduction: uses all 256 threads
    // per CTA for the compute-heavy Cin*K*K accumulation instead of
    // only 32 threads (1 warp) as before, fixing the severe warp
    // underutilization that capped achieved occupancy well below the
    // shared-memory-limited theoretical occupancy. ----
    activemask.b32 %r160;
    shfl.sync.bfly.b32 %f40, %f10, 4, 6175, %r160;
    add.f32 %f10, %f10, %f40;
    shfl.sync.bfly.b32 %f41, %f11, 4, 6175, %r160;
    add.f32 %f11, %f11, %f41;
    shfl.sync.bfly.b32 %f42, %f10, 2, 6175, %r160;
    add.f32 %f10, %f10, %f42;
    shfl.sync.bfly.b32 %f43, %f11, 2, 6175, %r160;
    add.f32 %f11, %f11, %f43;
    shfl.sync.bfly.b32 %f44, %f10, 1, 6175, %r160;
    add.f32 %f10, %f10, %f44;
    shfl.sync.bfly.b32 %f45, %f11, 1, 6175, %r160;
    add.f32 %f11, %f11, %f45;
    setp.ne.s32 %p19, %r152, 0;
    @%p19 bra COMPUTE_DONE;
    setp.ge.s32 %p16, %r17, %r5;
    @%p16 bra OUT1;
    mad.lo.s32 %r80, %r17, %r9, %r61;
    mad.lo.s32 %r80, %r80, %r10, %r145;
    mul.wide.s32 %rd20, %r80, 4;
    add.s64 %rd21, %rd19, %rd20;
    mul.wide.s32 %rd22, %r17, 4;
    add.s64 %rd23, %rd3, %rd22;
    ld.global.f32 %f30, [%rd23];
    add.f32 %f31, %f10, %f30;
    st.global.f32 [%rd21], %f31;
OUT1:
    add.s32 %r81, %r17, 1;
    setp.ge.s32 %p17, %r81, %r5;
    @%p17 bra COMPUTE_DONE;
    mad.lo.s32 %r82, %r81, %r9, %r61;
    mad.lo.s32 %r82, %r82, %r10, %r145;
    mul.wide.s32 %rd24, %r82, 4;
    add.s64 %rd25, %rd19, %rd24;
    mul.wide.s32 %rd26, %r81, 4;
    add.s64 %rd27, %rd3, %rd26;
    ld.global.f32 %f32, [%rd27];
    add.f32 %f33, %f11, %f32;
    st.global.f32 [%rd25], %f33;
COMPUTE_DONE:

    ret;
}
"""

_ENTRY_NAME = "conv2d_kernel"
_OC_PER_BLOCK = 2
_TILE_OH = 1
_TILE_OW = 32
_THREADS = 256


def validate_generated_code():
    """Compile the PTX module and confirm the kernel entry can be resolved."""
    module = PtxModule(PTX_SOURCE)
    fn = module.function(_ENTRY_NAME)
    assert fn is not None, f"entry '{_ENTRY_NAME}' not found in PTX module"
    return True


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        in_channels = 3
        out_channels = 96
        kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size, kernel_size))
        self.bias = nn.Parameter(torch.empty(out_channels))

        self.reset_parameters(in_channels, kernel_size)

        self._module = None

    def reset_parameters(self, in_channels, kernel_size):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = in_channels * kernel_size * kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def _get_module(self):
        if self._module is None:
            self._module = PtxModule(PTX_SOURCE)
        return self._module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be on CUDA device"

        module = self._get_module()

        x_c = x.contiguous()
        w_c = self.weight.contiguous()
        b_c = self.bias.contiguous()

        N, Cin, H, Win = x_c.shape
        Cout, _, K, _ = w_c.shape
        stride = self.stride
        padding = self.padding

        Hout = (H + 2 * padding - K) // stride + 1
        Wout = (Win + 2 * padding - K) // stride + 1
        assert Hout > 0 and Wout > 0, "invalid computed output size"

        y = torch.empty((N, Cout, Hout, Wout), device=x_c.device, dtype=x_c.dtype)

        num_oh_tiles = (Hout + _TILE_OH - 1) // _TILE_OH
        num_ow_tiles = (Wout + _TILE_OW - 1) // _TILE_OW
        num_oc_blocks = (Cout + _OC_PER_BLOCK - 1) // _OC_PER_BLOCK
        grid = (num_oh_tiles * num_ow_tiles, num_oc_blocks, N)
        block = (_THREADS, 1, 1)
        IH_TILE = (_TILE_OH - 1) * stride + K
        IW_TILE = (_TILE_OW - 1) * stride + K
        weight_sz = _OC_PER_BLOCK * Cin * K * K
        input_sz = Cin * IH_TILE * IW_TILE
        shared_mem_bytes = (weight_sz + input_sz) * 4
        # NOTE: the PTX kernel declares `smem_raw` as a statically-sized
        # `.shared` array sized for the exact fixed conv config used by this
        # kernel (TILE_OH=1, TILE_OW=32, K=11, stride=4, padding=2 =>
        # IH_TILE=11, IW_TILE=135, NUM_OW_TILES=2). TILE_OW was narrowed
        # from 64 to 32 (splitting each output row into 2 column tiles)
        # so the cached input tile (Cin*IH_TILE*IW_TILE) and thus the
        # per-CTA static shared-memory footprint shrinks from 37620 bytes
        # to 20724 bytes. Profiling showed theoretical occupancy was
        # capped at 33.3% purely because only 2 CTAs of the previous size
        # could co-reside per SM's shared-memory budget; halving the
        # per-CTA shared-memory usage lets roughly twice as many CTAs
        # (4 instead of 2) co-reside per SM, raising theoretical
        # occupancy toward 66.7% without altering the cooperative
        # tiling/staging algorithm itself.
        # No dynamic shared memory needs to be requested at launch time.
        # Keep this assertion as a guard so any change to the fixed config
        # is caught immediately instead of causing a silent
        # illegal-memory-access.
        assert shared_mem_bytes == 20724, (
            f"shared memory size mismatch: computed {shared_mem_bytes} bytes "
            "but the PTX statically allocates 20724 bytes; update the PTX "
            "smem_raw[] size if the fixed conv config changed"
        )

        stream = torch.cuda.current_stream(x_c.device)

        arg_list = [
            u64(x_c.data_ptr()),
            u64(w_c.data_ptr()),
            u64(b_c.data_ptr()),
            u64(y.data_ptr()),
            i32(N),
            i32(Cin),
            i32(H),
            i32(Win),
            i32(Cout),
            i32(K),
            i32(stride),
            i32(padding),
            i32(Hout),
            i32(Wout),
        ]
        launch_kwargs = dict(
            grid=grid,
            block=block,
            stream=stream,
        )
        sig_params = inspect.signature(module.launch).parameters
        shared_mem_kw_names = (
            "shared_mem",
            "shared_mem_bytes",
            "dyn_shared_mem",
            "dynamic_shared_mem",
            "smem_bytes",
            "smem",
            "shared_memory_bytes",
        )
        matched_kw = None
        for name in shared_mem_kw_names:
            if name in sig_params:
                matched_kw = name
                break
        if matched_kw is not None:
            launch_kwargs[matched_kw] = shared_mem_bytes
        else:
            fn = module.function(_ENTRY_NAME)
            if hasattr(fn, "set_shared_memory"):
                fn.set_shared_memory(shared_mem_bytes)
            elif hasattr(fn, "set_attribute"):
                fn.set_attribute("max_dynamic_shared_size_bytes", shared_mem_bytes)
            elif hasattr(fn, "set_max_dynamic_shared_size_bytes"):
                fn.set_max_dynamic_shared_size_bytes(shared_mem_bytes)
        arg_kw_candidates = ("args", "kernel_args", "params", "arguments", "kargs")
        matched_arg_kw = None
        for name in arg_kw_candidates:
            if name in sig_params:
                matched_arg_kw = name
                break
        if matched_arg_kw is not None:
            launch_kwargs[matched_arg_kw] = arg_list
            module.launch(_ENTRY_NAME, **launch_kwargs)
        elif any(p.kind == inspect.Parameter.VAR_POSITIONAL for p in sig_params.values()):
            module.launch(_ENTRY_NAME, *arg_list, **launch_kwargs)
        else:
            try:
                module.launch(_ENTRY_NAME, arg_list, **launch_kwargs)
            except TypeError:
                module.launch(
                    _ENTRY_NAME,
                    grid,
                    block,
                    arg_list,
                    **{k: v for k, v in launch_kwargs.items() if k not in ("grid", "block")},
                )

        return y

